contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(address target, uint256 value, bytes calldata data, bytes32 predecessor, bytes32 salt, uint256 delay) public payable {
        bytes32 adminRole = c.TIMELOCK_ADMIN_ROLE();
        bytes32 proposerRole = c.PROPOSER_ROLE();
        c.grantRole(proposerRole, address(this));
        require(c.hasRole(proposerRole, address(this)));
        bytes32 id = c.hashOperation(target, value, data, predecessor, salt);
        require(!c.isOperation(id));
        bool firstReverted;
        try c.schedule(target, value, data, predecessor, salt, delay) { firstReverted = false; } catch { firstReverted = true; }
        require(!firstReverted);
        uint256 ts = c.getTimestamp(id);
        bool pending = c.isOperationPending(id);
        bool secondReverted;
        try c.schedule(target, value, data, predecessor, salt, delay) { secondReverted = false; } catch { secondReverted = true; }
        assert(ts == block.timestamp + delay && pending && secondReverted);
    }
    receive() external payable {}
}

