contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(address target, uint256 minDelay, uint256 delay, bytes32 salt) public {
        require(delay > 0);

        // Grant this contract the roles it needs to schedule and execute.
        c.grantRole(c.PROPOSER_ROLE(), address(this));
        c.grantRole(c.EXECUTOR_ROLE(), address(this));

        require(c.getMinDelay() <= delay, "insufficient delay param");

        c.schedule(target, 0, "", bytes32(0), salt, delay);

        bytes32 id = c.hashOperation(target, 0, "", bytes32(0), salt);

        // Operation is scheduled and pending but not yet ready.
        require(c.isOperation(id), "not scheduled");
        require(!c.isOperationReady(id), "unexpectedly ready");

        // Executing before the delay elapses must revert.
        bool reverted;
        try c.execute(target, 0, "", bytes32(0), salt) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // The operation must remain pending (not done) since execution failed.
        assert(reverted && !c.isOperationDone(id) && c.isOperationPending(id));
    }

    receive() external payable {}
}

